   105	/// Tracks the set of currently-resolving binding identities (by graph index) so
   106	/// a re-export cycle terminates rather than recursing forever.
   107	pub(crate) const MAX_GLOB_DEPTH: usize = 2;
   108	
   109	struct CycleGuard<'s> {
   110	    /// Indices into `graph.bindings` currently on the resolution stack.
   111	    active: std::collections::BTreeSet<usize>,
   112	    /// Indices into `graph.edges` currently on the glob-expansion stack.
   113	    active_globs: std::collections::BTreeSet<usize>,
   114	    glob_depth: usize,
   115	    stats: Option<&'s GlobExpandStats>,
   116	}
   117	
   118	impl<'s> CycleGuard<'s> {
   119	    fn with_stats(stats: Option<&'s GlobExpandStats>) -> Self {
   120	        CycleGuard {
   121	            active: Default::default(),
   122	            active_globs: Default::default(),
   123	            glob_depth: 0,
   124	            stats,
   125	        }
   126	    }
   127	
   128	    /// Returns `false` if `idx` is already active (a cycle); otherwise marks it
   129	    /// active and returns `true`.
   130	    fn enter(&mut self, idx: usize) -> bool {
   131	        self.active.insert(idx)
   132	    }
   133	    fn leave(&mut self, idx: usize) {
   134	        self.active.remove(&idx);
   135	    }
   136	
   137	    fn glob_depth(&self) -> usize {
   138	        self.glob_depth
   139	    }
   140	
   141	    /// Returns `false` when this glob edge is already on the active chain.
   142	    fn enter_glob(&mut self, edge_idx: usize) -> bool {
   143	        if !self.active_globs.insert(edge_idx) {
   144	            return false;
   145	        }
   146	        self.glob_depth += 1;
   147	        true
   148	    }
   149	
   150	    fn leave_glob(&mut self, edge_idx: usize) {
   151	        self.active_globs.remove(&edge_idx);
   152	        self.glob_depth -= 1;
   153	    }
   154	
   155	    fn stats(&self) -> &GlobExpandStats {
   156	        self.stats
   157	            .unwrap_or(&crate::name_resolution::glob_stats::GLOBAL)
   158	    }
   159	
   160	    /// Enter a glob edge, run `body`, then leave on every successful entry.
   161	    fn with_glob<R>(&mut self, edge_idx: usize, body: impl FnOnce(&mut Self, bool) -> R) -> R {
   162	        let entered = self.enter_glob(edge_idx);
   163	        let r = body(self, entered);
   164	        if entered {
   165	            self.leave_glob(edge_idx);
   166	        }
   167	        r
   168	    }
   169	}
