   266	    graph: &ScopeGraph,
   267	    rib: &[usize],
   268	    q: &ResolveQuery,
   269	    policy: &dyn ResolutionPolicy,
   270	    guard: &mut CycleGuard<'_>,
   271	) -> Resolution {
