   274	        let b = &graph.bindings[bidx];
   275	        // Visibility is checked against the binding as found at this rib.
   276	        let trav = TraversalCtx {
   277	            lookup_scope: Some(b.scope),
   278	            via_glob: false,
   279	            edge_kind: None,
   280	        };
